import {cabinet,rect,circle,text,line,clamp,pick} from './cabinet.js';
import {swipeDirection} from './shared.js';
export function createSprint(mount,api){const q=cabinet(mount,api,{accent:'#88caff'}),c=q.c;let lane=1,x=180,obstacles=[],coins=[],spawn=0,life=3,shield=0,distance=0,earned=0,origin=null;
 function turn(to){if(!q.active)return;const n=clamp(to,0,2);if(n!==lane){lane=n;q.sound('lane');}}
 function laneAt(p){return clamp(Math.floor((p.x-36)/96),0,2);}
 return {start(){lane=1;x=180;obstacles=[];coins=[];spawn=.8;life=3;shield=0;distance=0;earned=0;origin=null;q.start();},tap(p){turn(laneAt(q.local(p)));},pointerDown(p){origin=q.local(p);},pointerUp(p){const d=swipeDirection(origin,q.local(p));origin=null;if(d==='left')turn(lane-1);if(d==='right')turn(lane+1);},cancel(){origin=null;},direction(d){if(d==='left')turn(lane-1);if(d==='right')turn(lane+1);},action(){turn((lane+1)%3);},tick(dt){q.frame(dt,dt=>{const speed=Math.min(350,195+q.elapsed*2.6);distance+=speed*dt/20;const total=Math.floor(distance);if(total>earned){q.add(total-earned);earned=total;}shield=Math.max(0,shield-dt);x+=(84+lane*96-x)*Math.min(1,dt*18);spawn-=dt;if(spawn<=0){const safe=pick([0,1,2]),occupied=[0,1,2].filter(n=>n!==safe);if(q.elapsed<8)occupied.splice(1,1);for(const n of occupied)obstacles.push({lane:n,y:-35,color:pick(['#c9b5ff','#ff92ad','#ffbe80']),hit:false});coins.push({lane:safe,y:-85,taken:false});spawn=1.25;}for(const o of obstacles){o.y+=speed*dt;if(!o.hit&&Math.abs(o.y-369)<42&&Math.abs((84+o.lane*96)-x)<38&&shield===0){o.hit=true;life--;shield=1.4;q.sound('crash');q.burst(x,369,'#ff8eac');q.say('SHIELD UP · keep moving');if(!life){q.finish('End of the road.',`${q.score} points. Leave room for the next opening.`);return;}}}for(const coin of coins){coin.y+=speed*dt;if(!coin.taken&&Math.abs(coin.y-369)<28&&Math.abs(84+coin.lane*96-x)<30){coin.taken=true;q.add(20);q.sound('coin');q.burst(x,coin.y,'#ffe28c',6);}}obstacles=obstacles.filter(o=>o.y<480);coins=coins.filter(o=>o.y<480&&!o.taken);if(q.elapsed>=60)q.finish('Clean getaway.',`One minute on the road. ${q.score} points.`,true);},()=>{q.header(`${'♥ '.repeat(life).trim()}`,`${Math.max(0,Math.ceil(60-q.elapsed))}s TO FINISH`);rect(c,33,40,294,395,'#1d293e',18);c.save();c.beginPath();c.roundRect(33,40,294,395,18);c.clip();for(let y=-50;y<450;y+=65){const yy=y+(distance*20)%65;line(c,132,yy,132,yy+28,'#acc9ff33');line(c,228,yy,228,yy+28,'#acc9ff33');}for(const coin of coins){circle(c,84+coin.lane*96,coin.y,11,'#ffe28c');text(c,'+',84+coin.lane*96,coin.y,16,'#6c572c',750);}for(const o of obstacles){const xx=84+o.lane*96;rect(c,xx-25,o.y-35,50,70,o.hit?'#745368':o.color,12);rect(c,xx-18,o.y-22,36,15,'#1e293b',5);rect(c,xx-18,o.y+18,36,8,'#ffffff33',3);}if(!shield||Math.floor(shield*15)%2){rect(c,x-25,338,50,65,'#88caff',12);rect(c,x-18,348,36,17,'#203b5c',6);rect(c,x-18,382,36,9,'#e8f7ff',4);}c.restore();q.footer('Tap a lane. Find the open road.');});},destroy:q.destroy};}
